Definition slpop (y : Z) : Z :=
  let t2 := Z.land (y / 2 ^ 1) C55 in
  let t3 := y - t2 in
  let t7 := Z.land t3 C33 + Z.land (t3 / 2 ^ 2) C33 in
  let t9 := t7 + t7 / 2 ^ 4 in
  let t10 := Z.land t9 C0F in
  (t10 * C01) mod 2 ^ 64 / 2 ^ 56.

